command:
/**
 * CreateItem Macro
 *
 * To embed this in a Journal, or an Item or Actor description,
 * use the following:
 * 
 * [[/mgMacro CreateItem name="Glass of Wine"]]{Take a drink}
 */

let itemName = "New Item";
let itemType = "item";

if (scope?.name) {
  console.log("Scope");
  if (scope.name) {
    itemName = scope.name;
  }
  if (scope.type) {
    itemType = scope.type;
  }
} else {
  console.log("Hello");
  const fields = foundry.applications.fields;
  const nameInput = fields.createTextInput({
    name: 'name',
    value: "Item Name"
  });
  const content=`
  <label>Item Name</label>
  ${nameInput.outerHTML}
  `;
  const data = await foundry.applications.api.DialogV2.input({
    window: { title: "Create Item"},
    content: content,
    ok: {
      label: "Create"
    }
  });
}
// Add item to token
for (let t of canvas.tokens.controlled) {
    let actor = t.actor;
    if (actor) {
       const itemData = {
         "name": itemName,
         "img": "",
         "type": itemType,
         "system": {
           "status": "carried"
         }
       }
       Item.create(itemData, { parent: actor });
    }
}
